import{c as a,Q as t,j as r,m as o}from"./chunks/framework.DOi4mjdC.js";const l="/assets/SIMT%E6%8A%BD%E8%B1%A1%E7%A1%AC%E4%BB%B6%E6%9E%B6%E6%9E%84%E5%9B%BE.dmp7a7hs.png",h=JSON.parse('{"title":"抽象硬件架构","description":"","frontmatter":{},"headers":[{"level":1,"title":"抽象硬件架构","slug":"抽象硬件架构"}],"relativePath":"guide/编程指南/编程模型/AI-Core-SIMT编程/抽象硬件架构.md","filePath":"guide/编程指南/编程模型/AI-Core-SIMT编程/抽象硬件架构.md"}'),i={name:"guide/编程指南/编程模型/AI-Core-SIMT编程/抽象硬件架构.md"};function s(n,e,_,c,f,p){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="抽象硬件架构" tabindex="-1">抽象硬件架构 <a class="header-anchor" href="#抽象硬件架构" aria-label="Permalink to &quot;抽象硬件架构&quot;">​</a></h1><p>AI Core上的SIMT（Single Instruction Multiple Thread，单指令多线程）编程允许指令对数据进行独立寻址，从而支持线程级并行计算。这种方式特别适用于离散访问和复杂控制逻辑等场景，目前仅支持Atlas 350 加速卡。</p><p>SIMT编程能够简化复杂算子和不规则控制流的开发，通过SIMT编程可以有效缓解包含分支等的发散计算，同时控制程序复杂度。在系统层面，这有助于提高硬件利用率和能效。如<a href="#fig35720259287">图1</a>所示，AI处理器内部有多个Vector Core，每个Vector Core包含计算单元、Share Memory即Unified Buffer、寄存器和堆栈空间，核外的Global Memory是全局内存空间，被所有Vector Core共享。</p><p><strong>图 1</strong> SIMT抽象硬件架构图<br><img src="'+l+'" alt="" title="SIMT抽象硬件架构图"></p><p>以下是SIMT多线程计算涉及到的硬件资源的说明：</p><ul><li>每个线程拥有独立的寄存器和栈空间，用于存储局部数据， 寄存器的数量受线程块内线程数量影响，线程数量越多，每个线程拥有的寄存器数量越少。</li><li>Unified Buffer的一部分内存空间作为线程块内所有线程的共享内存（Share Memory），支持线程块内的线程进行数据交互，一部分作为读取Global Memory的Data Cache。</li><li>SIMT模式中，读取Global Memory上的数据时，通过Data Cache单元完成数据中转，数据流经由Global Memory到Data Cache，再从Data Cache到寄存器。Data Cache是Unified Buffer中预留的一部分空间，其最大容量为128KB，最小容量为32KB，实际大小由用户自主分配。</li></ul><p>若您对上述内容中的线程、线程块等概念不熟悉，建议查阅<a href="./线程架构.html">线程架构</a>了解更多SIMT线程架构知识；同时，您也可以通过阅读<a href="./内存层级.html">内存层级</a>，了解如何配置Data Cache、Unified Buffer的划分方式。</p>',7)])])}const m=a(i,[["render",s]]);export{h as __pageData,m as default};
